ALTER TABLE public.client_tasks ADD COLUMN exit_withdrawn boolean NOT NULL DEFAULT false;
DO $$ DECLARE s text; BEGIN
SELECT pg_get_functiondef(oid) INTO s FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='record_termination_notice'; s:=replace(s,'''EXIT.''||e.code','''EXIT.''||e.code||CASE WHEN EXISTS(SELECT 1 FROM client_tasks old WHERE old.launch_id=l.id AND old.phase=''offboarding'' AND old.exit_withdrawn) THEN ''.''||txid_current()::text ELSE '''' END'); EXECUTE s;
SELECT pg_get_functiondef(oid) INTO s FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='withdraw_termination_notice'; s:=replace(s,'DELETE FROM client_tasks WHERE launch_id = l.id AND phase = ''offboarding'' AND status <> ''done''','UPDATE client_tasks SET exit_withdrawn=true WHERE launch_id=l.id AND phase=''offboarding'''); EXECUTE s;
SELECT pg_get_functiondef(oid) INTO s FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='exit_workspace'; s:=replace(s,'WHERE t.phase=''offboarding''','WHERE t.phase=''offboarding'' AND NOT t.exit_withdrawn'); EXECUTE s;
SELECT pg_get_functiondef(oid) INTO s FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='exit_closure_guard'; s:=replace(s,'phase=''offboarding''','phase=''offboarding'' AND NOT exit_withdrawn'); EXECUTE s;
SELECT pg_get_functiondef(oid) INTO s FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='update_exit_item'; s:=replace(s,'t.phase<>''offboarding''','t.phase<>''offboarding'' OR t.exit_withdrawn'); EXECUTE s;
END $$;
CREATE FUNCTION public.exit_history_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.exit_withdrawn AND to_jsonb(OLD) IS DISTINCT FROM to_jsonb(NEW) THEN RAISE EXCEPTION 'Withdrawn exit history is read-only'; END IF; IF NEW.exit_withdrawn IS DISTINCT FROM OLD.exit_withdrawn AND NOT (can_edit_client(OLD.client_id) OR is_launch_am(OLD.launch_id)) THEN RAISE EXCEPTION 'Only authorized managers may withdraw exit items'; END IF; RETURN NEW; END $$;
CREATE TRIGGER a0_exit_history_guard BEFORE UPDATE ON public.client_tasks FOR EACH ROW EXECUTE FUNCTION public.exit_history_guard();